pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address token, address[] calldata tos, uint256 v, uint256 decimals) public {
        // Bound values to avoid overflow/underflow in the contract
        vm.assume(v < 10_000 && decimals < 10);
        vm.assume(tos.length > 0 && tos.length <= 10);
        // Ensure token address is a contract (e.g., not zero)
        vm.assume(token != address(0) && token.code.length > 0);

        // Record initial balance of token contract (simulate a token with balanceOf)
        (bool success, bytes memory data) = address(token).staticcall(
            abi.encodeWithSignature("balanceOf(address)", address(c))
        );
        vm.assume(success);
        uint256 initialBalance = abi.decode(data, (uint256));

        // Compute sum of amounts transferred
        uint256 totalValue = v * (10 ** decimals);
        uint256 sumTransferred = totalValue * tos.length;

        // Ensure no overflow
        vm.assume(initialBalance + sumTransferred > initialBalance); // no overflow

        // Call the transfer function
        c.transfer(from, token, tos, v, decimals);

        // Check final balance
        (success, data) = address(token).staticcall(
            abi.encodeWithSignature("balanceOf(address)", address(c))
        );
        require(success, "balanceOf call failed");
        uint256 finalBalance = abi.decode(data, (uint256));

        // The reference C uses transferFrom (pulls from sender) so finalBalance >= initialBalance - sumTransferred (it can be more if token transfers back? but generally it should be >= initialBalance - sumTransferred)
        // For the mutant, using transfer, tokens are sent from this contract to recipients, so finalBalance <= initialBalance - sumTransferred (if no other transfers)
        // A general invariant: The balance change should not be negative beyond the sum transferred.
        assertTrue(finalBalance >= initialBalance - sumTransferred, "Balance decreased more than transferred amounts");
    }
}

