pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] calldata _tos, uint v, uint _decimals) public {
        vm.assume(_tos.length > 0);
        // Create a malicious token contract that reverts on transferFrom
        // but only on the last call. If the loop skips the last element, call succeeds.
        // We achieve this by deploying a contract that uses a counter.
        RevertingToken token = new RevertingToken();
        // Replace caddress with the reverting token
        (bool success,) = address(c).call(abi.encodeWithSignature(
            "transfer(address,address,address[],uint256,uint256)",
            from, address(token), _tos, v, _decimals
        ));
        // If the loop goes to _tos.length, it reverts on last call => success should be false
        // If the loop goes to _tos.length - 1, it skips last call => success true
        // The reference C must revert (success false) because it processes all elements
        assertTrue(!success, "transfer must not succeed when the last recipient reverts");
    }
}

contract RevertingToken {
    uint counter;
    // Fallback reverts on every third call (i.e., when counter % 2 == 1, we simulate last element)
    fallback() external payable {
        counter++;
        if (counter % 2 == 0) {
            revert("revert");
        }
    }
}

